import { useState } from 'react';

import {
  BASEMAPS,
  defaultBasemapId,
  notifyBasemapChanged,
  saveBasemapId,
} from '../lib/basemaps';

/** Compact select in the map corner: pick a keyless basemap style. */
export default function BasemapPicker({ className = '' }: { className?: string }) {
  const [id, setId] = useState(defaultBasemapId);

  const apply = (next: string) => {
    setId(next);
    saveBasemapId(next);
    notifyBasemapChanged(next);
  };

  return (
    <select
      value={id}
      onChange={(e) => apply(e.target.value)}
      aria-label="Basemap style"
      title="Basemap style"
      className={`pointer-events-auto h-7 cursor-pointer rounded border border-border bg-card px-1 text-[10px] font-medium text-text-secondary shadow-sm outline-none hover:bg-card-hover ${className}`}
    >
      {BASEMAPS.map((b) => (
        <option key={b.id} value={b.id}>
          {b.label}
        </option>
      ))}
    </select>
  );
}